// Transition-cell lookup data from Eric Lengyel's Transvoxel reference implementation.
// Source: https://github.com/Jarred-Sumner/transvoxel-data
// Licensed under the MIT License; see Archive/ThirdParty/Transvoxel-LICENSE.txt.
internal readonly record struct VoxelTransitionCellData( byte Geometry, byte[] TriangleIndices )
{
	public int VertexCount => Geometry >> 4;
	public int TriangleCount => Geometry & 0x0F;
}

internal static class VoxelTransvoxelTransitionTables
{
	private const string CellClassBase64 = "";
	private const string CellDataBase64 = "";
	private const string CornerDataBase64 = "MAAhACAAEgBAAIIAEACBAIAANwAnABcAhwA=";

	public static readonly byte[] CellClass = System.Convert.FromBase64String( CellClassBase64 );
	private const string VertexDataChunk0 = "";
	private const string VertexDataChunk1 = "";
	private const string VertexDataChunk2 = "";
	private const string VertexDataChunk3 = "";
	private const string VertexDataChunk4 = "";
	private const string VertexDataChunk5 = "";
	private const string VertexDataBase64 = VertexDataChunk0 + VertexDataChunk1 + VertexDataChunk2 + VertexDataChunk3 + VertexDataChunk4 + VertexDataChunk5;
	public static readonly ushort[] VertexData = DecodeUShorts( VertexDataBase64 );
	public static readonly ushort[] CornerData = DecodeUShorts( CornerDataBase64 );
	public static readonly VoxelTransitionCellData[] CellData = DecodeCellData();

	private static VoxelTransitionCellData[] DecodeCellData()
	{
		var bytes = System.Convert.FromBase64String( CellDataBase64 );
		var data = new VoxelTransitionCellData[56];
		var offset = 0;
		for ( var index = 0; index < data.Length; index++ )
		{
			if ( offset >= bytes.Length ) throw new System.InvalidOperationException( "Transvoxel transition-cell data is truncated." );
			var geometry = bytes[offset++];
			var indexCount = (geometry & 0x0F) * 3;
			if ( offset + indexCount > bytes.Length ) throw new System.InvalidOperationException( "Transvoxel transition-cell indices are truncated." );
			var indices = new byte[indexCount];
			System.Array.Copy( bytes, offset, indices, 0, indexCount );
			offset += indexCount;
			data[index] = new VoxelTransitionCellData( geometry, indices );
		}
		if ( offset != bytes.Length ) throw new System.InvalidOperationException( "Transvoxel transition-cell data has trailing bytes." );
		return data;
	}

	private static ushort[] DecodeUShorts( string base64 )
	{
		var bytes = System.Convert.FromBase64String( base64 );
		var values = new ushort[bytes.Length / sizeof( ushort )];
		System.Buffer.BlockCopy( bytes, 0, values, 0, bytes.Length );
		return values;
	}
}
